/* vplat (minimal slice): a UART putchar wired into newlib's console stubs.
 *
 * This is the first piece of the portable runtime that replaces -lgloss_vh
 * (semihosting): it points newlib's stdout at the ATCUART100 UART2 that BOTH
 * engines model at the same address, so a printf reaches host stdout on QEMU
 * (fast), on vsim (cycle), and across a hybrid handoff -- with no "which engine
 * am I on" probe, which would go stale at the handoff.
 *
 * Only the console channel (fd 0-2) is served here. Exit and file io still fall
 * back to the semihost libgloss; the completion slice adds SimControl exit +
 * HTIF file io and drops that fallback.
 */

#include <stdint.h>
#include <stddef.h>
#include <sys/stat.h>
#include <unistd.h>

/* ---- UART2 (console) ------------------------------------------------- */

#define UART_THR (*(volatile uint32_t*) 0xf0300020UL)
#define UART_LSR (*(volatile uint32_t*) 0xf0300034UL)
#define UART_LSR_THRE 0x20u

static void uart_putc(char c)
{
  while (!(UART_LSR & UART_LSR_THRE))
    ;
  UART_THR = (uint32_t) (unsigned char) c;
}

/* ---- newlib console stubs -------------------------------------------- */

__attribute__((used)) ssize_t _write(int fd, const void* ptr, size_t len)
{
  (void) fd;
  for (size_t i = 0; i < len; ++i)
    uart_putc(((const char*) ptr)[i]);
  return (ssize_t) len;
}

__attribute__((used)) int _fstat(int fd, struct stat* st)
{
  (void) fd;
  st->st_mode = S_IFCHR; /* char device -> newlib line-buffers stdout */
  return 0;
}

__attribute__((used)) int _isatty(int fd)
{
  (void) fd;
  return 1;
}

__attribute__((used)) void* _sbrk(intptr_t increment)
{
  extern char _end[];
  static char* p = _end;
  void* base = p;
  p += increment;
  return base;
}

/* crt0.S unconditionally calls init_mtvec. The real trap-vector setup lives in
 * handler.c, which arrives in the completion slice; this no-op keeps the
 * minimal runtime linkable (vplat_hello takes no traps on the fast path). */
__attribute__((used)) void init_mtvec(void) {}
